# Exact-mode audit verifier. No imports, no filesystem, no network, no print, no raise, deterministic, exact integer arithmetic only. Fail-closed: any anomaly yields False.

def parse_decimal_exact(s):
    if not isinstance(s, str):
        return None
    t = s.strip()
    if len(t) == 0:
        return None
    if '/' in t or 'e' in t.lower() or 'i' in t.lower() or 'n' in t.lower() or 'a' in t.lower():
        return None
    sign = 1
    if t[0] == '+':
        t = t[1:]
    elif t[0] == '-':
        sign = -1
        t = t[1:]
    if len(t) == 0:
        return None
    parts = t.split('.')
    if len(parts) > 2:
        return None
    for p in parts:
        if not p.isdigit():
            return None
    if len(parts) == 1:
        num = int(parts[0])
        den = 1
    else:
        intpart, fracpart = parts
        if intpart == '' and fracpart == '':
            return None
        if intpart == '':
            intpart = '0'
        num = int(intpart + fracpart)
        den = 10 ** len(fracpart)
    num = num * sign
    a, b = abs(num), den
    while b != 0:
        a, b = b, a % b
    g = a if a != 0 else 1
    return (num // g, den // g)

def frac_eq(f, num, den):
    if den == 0:
        return False
    a, b = abs(num), abs(den)
    while b != 0:
        a, b = b, a % b
    g = a if a != 0 else 1
    rn = num // g
    rd = den // g
    if rd < 0:
        rn = -rn
        rd = -rd
    return f[0] == rn and f[1] == rd

exact_cases = [
    ("E1", 3599, 1000, "3.599", True),
    ("E2", 1, 3, "0.3333333333333333", False),
    ("E3", 70710678118654752487, 100000000000000000000, "0.70710678118654752487", True),
    ("E4", 220001, 70000, "3.143", False)
]

injection_cases = [
    ("I1", 1, 3, "not-a-number", True),
    ("I2", 1, 0, "", True),
    ("I3", 1, 3, "1/3", True)
]

def verify():
    for cid, num, den, lit, expect in exact_cases:
        f = parse_decimal_exact(lit)
        if f is None:
            return False
        if frac_eq(f, num, den) != expect:
            return False
    for cid, num, den, lit, must_fail in injection_cases:
        triggered = False
        if den == 0:
            triggered = True
        else:
            f = parse_decimal_exact(lit)
            if f is None:
                triggered = True
        if must_fail and not triggered:
            return False
    f3 = parse_decimal_exact("0.70710678118654752487")
    if f3 is None:
        return False
    if not frac_eq(f3, 70710678118654752487, 100000000000000000000):
        return False
    return True

VERIFY_RESULT = verify()
STATUS = "PASS" if VERIFY_RESULT else "FAIL"
